export interface ConnectorConfig {
  airtableApiKey: string;
  airtableBaseId: string;
  airtableTableName: string;
  fetch?: typeof fetch;
  defaultEmail?: string;
}

export interface ShopifyOrderPaidPayload {
  id: string;
  totals: Array<{
    type: string;
    amount: number;
    display_text?: string;
  }>;
  email?: string;
  ucp?: unknown;
  label?: string;
  currency?: string;
  line_items?: unknown[];
  fulfillment?: unknown;
}

export interface HandleResult {
  recordId: string;
  fields: {
    "Order ID": string;
    Email: string;
    Total: number;
  };
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!payload.id) {
    throw new Error("Missing required field: payload.id (order ID)");
  }
  if (!payload.totals || !Array.isArray(payload.totals)) {
    throw new Error("Missing required field: payload.totals (array of totals)");
  }

  const totalEntry = payload.totals.find((t) => t.type === "total");
  if (!totalEntry || typeof totalEntry.amount !== "number") {
    throw new Error("Missing required field: payload.totals entry with type='total' and numeric amount");
  }

  const email = payload.email ?? config.defaultEmail;
  if (!email) {
    throw new Error("Missing required field: customer email (provide in payload.email or config.defaultEmail)");
  }

  const orderId = payload.id;
  const total = totalEntry.amount / 100;

  const fetchImpl = config.fetch ?? fetch;
  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableName}`;

  const response = await fetchImpl(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${config.airtableApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      fields: {
        "Order ID": orderId,
        Email: email,
        Total: total,
      },
    }),
  });

  if (!response.ok) {
    throw new Error(`Airtable API error: ${response.status} ${response.statusText} at POST ${url}`);
  }

  const result = (await response.json()) as { id: string; fields: HandleResult["fields"]; createdTime: string };

  return {
    recordId: result.id,
    fields: result.fields,
  };
}

