  it("happy path: creates record with correct field mapping", async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === "https://api.airtable.com/v0/appTestBase/tblTestTable"
        ? jsonResponse(
            { id: "rec123", fields: { "Order ID": "gid://shopify/Order/123", Email: "test@example.com", Total: 99.99 }, createdTime: "2024-01-01T00:00:00.000Z" },
            201
