      id: "gid://shopify/Order/123",
      totals: [
        { type: "subtotal", amount: 5000 },
        { type: "total", amount: 9999 },
      ],
      email: "test@example.com",
    };

    const result = await handle(payload, { ...baseConfig, fetch });

    expect(result.recordId).toBe("rec123");
    expect(result.fields["Order ID"]).toBe("gid://shopify/Order/123");
    expect(result.fields.Email).toBe("test@example.com");
    expect(result.fields.Total).toBe(99.99);

